//! The protocol between bluecaster-core.exe and the UI: the message and state
//! types ([`protocol`], TypeScript bindings generated by ts-rs into
//! app/src/ui/src/ipc/bindings with `cargo test -p ipc export_bindings`), and the
//! transport: length-prefixed JSON frames over the user's Named Pipe
//! `\\.\pipe\bluecaster-<user SID>` (the server side, with a DACL for that user
//! only, is in win-sys).

#![forbid(unsafe_code)]

pub mod protocol;

pub use protocol::*;

use serde::Serialize;
use serde::de::DeserializeOwned;
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};

/// Frames larger than this are refused (a snapshot is a few kB)
pub const MAX_FRAME: usize = 4 << 20;

/// Development: `BLUECASTER_INSTANCE=<name>` gives a core its own pipe and
/// instance mutex, so that it runs beside the installed one (together with
/// `BLUECASTER_CONFIG_DIR` for a test folder). Letters, digits, '-' and '_' (up
/// to 32); anything else is ignored. Empty for the normal instance.
pub fn instance_suffix() -> String {
    match std::env::var("BLUECASTER_INSTANCE") {
        Ok(v)
            if !v.is_empty()
                && v.len() <= 32
                && v.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_') =>
        {
            format!("-{v}")
        }
        _ => String::new(),
    }
}

/// The user's pipe, from the user's SID string (S-1-5-21-...)
pub fn pipe_name(user_sid: &str) -> String {
    format!(r"\\.\pipe\bluecaster-{user_sid}{}", instance_suffix())
}

/// The mutex the resident core holds while it runs (per logon session)
pub fn core_mutex_name() -> String {
    format!(r"Local\A2DPWB_v2_Core{}", instance_suffix())
}

#[derive(Debug, thiserror::Error)]
pub enum FrameError {
    #[error("I/O: {0}")]
    Io(#[from] std::io::Error),
    #[error("frame of {0} bytes is too large")]
    TooLarge(usize),
    #[error("bad message: {0}")]
    Json(#[from] serde_json::Error),
}

/// Writes one frame: length (u32 LE) and the JSON
pub async fn write_frame<W: AsyncWrite + Unpin, T: Serialize>(w: &mut W, msg: &T) -> Result<(), FrameError> {
    let json = serde_json::to_vec(msg)?;
    if json.len() > MAX_FRAME {
        return Err(FrameError::TooLarge(json.len()));
    }
    let mut buf = Vec::with_capacity(4 + json.len());
    buf.extend_from_slice(&(json.len() as u32).to_le_bytes());
    buf.extend_from_slice(&json);
    w.write_all(&buf).await?;
    w.flush().await?;
    Ok(())
}

/// Reads one frame; Ok(None) at the end of the stream
pub async fn read_frame<R: AsyncRead + Unpin, T: DeserializeOwned>(r: &mut R) -> Result<Option<T>, FrameError> {
    let mut len = [0u8; 4];
    match r.read_exact(&mut len).await {
        Ok(_) => {}
        Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Ok(None),
        Err(e) => return Err(e.into()),
    }
    let len = u32::from_le_bytes(len) as usize;
    if len > MAX_FRAME {
        return Err(FrameError::TooLarge(len));
    }
    let mut buf = vec![0u8; len];
    r.read_exact(&mut buf).await?;
    Ok(Some(serde_json::from_slice(&buf)?))
}

#[cfg(test)]
mod tests {
    use super::*;
    use ts_rs::TS;

    #[tokio::test(flavor = "current_thread")]
    async fn frames_round_trip() {
        let (mut a, mut b) = tokio::io::duplex(64);
        let msg = ClientMessage::Hello { protocol: PROTOCOL_VERSION, client: "test".into() };
        let send = msg.clone();
        let writer = async move { write_frame(&mut a, &send).await.unwrap() };
        let reader = async { read_frame::<_, ClientMessage>(&mut b).await.unwrap() };
        let ((), got) = tokio::join!(writer, reader);
        assert_eq!(got, Some(msg));
        assert!(read_frame::<_, ClientMessage>(&mut b).await.unwrap().is_none());
    }

    /// Writes the TypeScript bindings to app/src/ui/src/ipc/bindings
    #[test]
    fn export_bindings() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../ui/src/ipc/bindings");
        std::fs::create_dir_all(&dir).unwrap();
        let cfg = ts_rs::Config::new().with_out_dir(&dir);
        ClientMessage::export_all(&cfg).unwrap();
        ServerMessage::export_all(&cfg).unwrap();
        LinkSample::export_all(&cfg).unwrap();
        AudioDevice::export_all(&cfg).unwrap();
        AudioApp::export_all(&cfg).unwrap();
        DiagInfo::export_all(&cfg).unwrap();
        FlowView::export_all(&cfg).unwrap();
        AdapterInfo::export_all(&cfg).unwrap();
        Method::export_all(&cfg).unwrap();
        FirmwareFile::export_all(&cfg).unwrap();
        ReceiverState::export_all(&cfg).unwrap();
        DiagInfoParams::export_all(&cfg).unwrap();
        SettingsApplied::export_all(&cfg).unwrap();
        DiagBundle::export_all(&cfg).unwrap();
        DiagBundleParams::export_all(&cfg).unwrap();
        RfcommOpened::export_all(&cfg).unwrap();
    }
}
